def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    # Find all primes less than 100
    primes = [p for p in range(2, 100) if is_prime(p)]

    # Check if a can be written as product of exactly 3 primes (with repetition allowed)
    # We need to find three primes p1, p2, p3 such that p1 * p2 * p3 == a
    # Since order doesn't matter, we can iterate with p1 <= p2 <= p3
    for i, p1 in enumerate(primes):
        if p1 * p1 * p1 > a:
            break
        for j in range(i, len(primes)):
            p2 = primes[j]
            if p1 * p2 * p2 > a:
                break
            for k in range(j, len(primes)):
                p3 = primes[k]
                product = p1 * p2 * p3
                if product == a:
                    return True
                if product > a:
                    break
    return False
